const html = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const statuses = {queued:'Da avviare',running:'In lavorazione',review:'Da approvare',completed:'Approvato',failed:'Interrotto',paused:'In pausa'};
const stages = {queued:'In attesa del tuo avvio',preparing:'Preparazione della copia di lavoro',editing:'Modifiche al codice',checking:'Controlli in esecuzione',reviewing:'Revisione del codice',review:'Modifiche da controllare',completed:'Patch approvata',failed:'Il lavoro richiede attenzione',paused:'Lavoro fermato'};
const checkNames = {pending:'In attesa',running:'In corso',passed:'Superato',failed:'Fallito',error:'Errore',skipped:'Non eseguito'};
const date = value => {const d=new Date(value);return value&&Number.isFinite(d.getTime())?new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(d):'—';};
const badge = run => `<span class="ops-state state-${html(run.status)}">${html(statuses[run.status]||run.status)}</span>`;
const help = (label,text) => `<details class="repo-help"><summary aria-label="Aiuto: ${html(label)}">?</summary><p>${html(text)}</p></details>`;
let fieldSequence=0;
const field = (label,name,value='',area=false) => `<div class="ops-field"><label for="repo-field-${name}-${fieldSequence+1}">${html(label)}</label>${area?`<textarea id="repo-field-${name}-${++fieldSequence}" name="${name}" rows="5" maxlength="16000" required>${html(value)}</textarea>`:`<input id="repo-field-${name}-${++fieldSequence}" name="${name}" value="${html(value)}" maxlength="1000" required autocomplete="off">`}</div>`;

export function createRepositoriesPanel({host,toast=()=>{},onActivity=()=>{},onRefreshMemory=async()=>{},onNewProject=()=>{},onOutcome=()=>{}}={}) {
  let snapshot={repositories:[],runs:[],available:false,localOnly:true},context={projects:[],scopes:[],scopeId:'business',filter:'current',projectId:null};
  let loaded=false,loading=false,saving=false,busy=false,visible=false,error='',pollTimer=null,polling=false,disposed=false,loadVersion=0,view=null,patchLoading=false;
  const patches=new Map();
  const dialog=document.createElement('dialog');dialog.id='repositories-dialog';dialog.className='ops-dialog repo-dialog';dialog.setAttribute('aria-labelledby','repo-dialog-title');document.body.append(dialog);
  const repository=id=>snapshot.repositories.find(item=>item.id===id),runFor=id=>snapshot.runs.find(item=>item.id===id);
  const project=id=>context.projects.find(item=>item.id===id),scopeName=id=>context.scopes.find(item=>item.id===id)?.name||id;
  const allowed=item=>context.filter==='all'||item.scopeId===context.scopeId;
  const locked=()=>loading||saving||busy||!snapshot.available;
  const passed=run=>run.status==='review'&&run.decision?.status!=='changes_requested'&&Boolean(run.patchHash)&&run.checksValid===true&&run.files?.length>0&&run.checks?.length>0&&run.checks.every(check=>check.status==='passed'&&check.exitCode===0);
  function accept(value) {
    if(!value||!Array.isArray(value.repositories)||!Array.isArray(value.runs))throw Error('I dati dei repository non sono disponibili.');
    snapshot=value;loaded=true;error='';onActivity(snapshot);render();schedule();
  }
  async function request(body) {
    const response=await fetch('/api/repositories',body?{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:JSON.stringify(body)}:{cache:'no-store'});
    let value;try{value=await response.json();}catch{throw Error('Il server non ha risposto correttamente.');}
    if(disposed)throw Error('Sessione scaduta.');
    if(!response.ok){const e=Error(value.error||'Operazione non riuscita.');e.status=response.status;throw e;}return value;
  }
  async function load({quiet=false}={}) {
    if(disposed)return;
    const version=++loadVersion;
    if(!quiet){loading=true;error='';render();}
    try{const value=await request();if(version!==loadVersion||disposed)return;loading=false;accept(value);if(view?.kind==='run'&&dialog.open)showRun(view.id);}
    catch(e){if(version!==loadVersion||disposed)return;loading=false;error=e.message;render();}
    finally{schedule();}
  }
  function schedule(){clearTimeout(pollTimer);if(!disposed&&document.visibilityState==='visible'&&snapshot.runs.some(run=>run.status==='running'))pollTimer=setTimeout(poll,3000);}
  async function poll(){if(polling||loading||saving||document.hidden){schedule();return;}polling=true;try{await load({quiet:true});}finally{polling=false;schedule();}}
  function visibility(){if(!document.hidden&&snapshot.runs.some(run=>run.status==='running'))void poll();else schedule();}
  document.addEventListener('visibilitychange',visibility);
  function expire(){disposed=true;clearTimeout(pollTimer);loadVersion++;if(dialog.open)dialog.close();}
  window.addEventListener('studio-session-expired',expire);
  async function mutation(action,payload) {
    const value=await request({action,payload});
    if(Array.isArray(value.runs))accept(value);else await load({quiet:true});
    if(action==='proposeMemory')await onRefreshMemory();return value;
  }
  function syncLocks(){host.querySelectorAll('[data-repo-mutation]').forEach(el=>el.disabled=locked());dialog.querySelectorAll('[data-repo-mutation],button[type="submit"]').forEach(el=>el.disabled=locked());dialog.querySelectorAll('[data-repo-action="approve"]').forEach(el=>el.disabled=locked()||!passed(runFor(el.dataset.id)||{}));}
  function checkCommand(check){return [check.program,...(check.args||[]).map(arg=>/^[\w./:-]+$/.test(arg)?arg:JSON.stringify(arg))].join(' ');}
  function card(repo) {
    const runs=snapshot.runs.filter(run=>run.repositoryId===repo.id).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));
    return `<article class="repo-card"><div class="repo-card-heading"><div><span class="repo-kicker">${html(project(repo.projectId)?.title||'Progetto')} · ${html(scopeName(repo.scopeId))}</span><h3>${html(repo.name||repo.path.split('/').at(-1))}</h3></div><span class="repo-local">Locale</span></div><code class="repo-path">${html(repo.path)}</code><div class="repo-facts"><span>${html(repo.branch||'HEAD separato')}</span><code>${html(repo.head?.slice(0,10)||'HEAD')}</code><span>${repo.dirty?'Modifiche locali escluse':'Copia sorgente pulita'}</span></div><div class="repo-card-bottom"><span>${repo.checks?.length||0} controlli definiti · ${runs.length} incarich${runs.length===1?'o':'i'}</span><button type="button" class="ops-button is-primary" data-repo-action="create" data-id="${html(repo.id)}" data-repo-mutation>＋ Incarico sul codice</button></div>${runs.length?`<div class="repo-runs">${runs.map(run=>`<button type="button" class="repo-run" data-repo-action="run" data-id="${html(run.id)}"><span><strong>${html(run.title)}</strong><small>${html(stages[run.stage]||run.stage||statuses[run.status])} · ${html(date(run.updatedAt))}</small></span>${badge(run)}<span aria-hidden="true">↗</span></button>`).join('')}</div>`:''}</article>`;
  }
  function render() {
    if(!visible)return;
    const repos=snapshot.repositories.filter(allowed),projects=context.projects.filter(allowed);
    host.innerHTML=`<div class="repo-intro"><div><div class="repo-title-row"><h3>Dal progetto al codice.</h3>${help('Come lavora sul repository','Si parte dall’ultimo commit HEAD, in una copia isolata. I file locali non salvati in un commit sono esclusi. Codex e i controlli eseguono codice sul computer dello studio. Usa repository e comandi di cui ti fidi. Approvare una patch non modifica, integra o pubblica il repository originale.')}</div><p>Una copia di lavoro separata, controlli espliciti e una patch che approvi tu.</p></div><button type="button" class="ops-button is-primary" data-repo-action="register" data-repo-mutation>Collega repository</button></div>${loading?'<p class="repo-notice" role="status">Caricamento dei repository…</p>':error?`<p class="ops-error" role="alert">${html(error)} <button type="button" class="ops-text-button" data-repo-action="refresh">Riprova</button></p>`:!snapshot.available?`<div class="repo-empty"><span aria-hidden="true">⌘</span><h3>Il codice lavora sul tuo computer.</h3><p>${snapshot.reason?html(snapshot.reason):'Questa funzione richiede uno studio locale con Git e il runtime Codex disponibili.'}</p><p>Collegamenti, memorie e normali incarichi restano disponibili nelle altre schede.</p></div>`:repos.length?`<div class="repo-grid">${repos.map(card).join('')}</div>`:`<div class="repo-empty"><span aria-hidden="true">⌘</span><h3>${projects.length?'Collega il codice al suo progetto.':'Prima, scegli un progetto.'}</h3><p>${projects.length?'Seleziona un progetto già creato, il percorso di una repository Git su questo computer e i controlli da eseguire. Poi prepara un incarico e avvialo quando sei pronto.':'Crea un progetto dello studio oppure mostra tutti gli ambiti per collegarne uno esistente.'}</p><ol><li>Collega una repository locale</li><li>Descrivi la modifica e avvia Codex</li><li>Controlla test, diff e revisione</li></ol><button type="button" class="ops-button" data-repo-action="${projects.length?'register':'new-project'}">${projects.length?'Collega il primo repository':'Crea un progetto'}</button></div>`}<p class="repo-footnote">Solo Codex locale · Avvio a consumo esplicito · Approvazione senza merge o push</p>`;
    syncLocks();
  }
  function shell(title,body,footer) {
    dialog.innerHTML=`<div class="ops-dialog-heading"><div><div class="eyebrow">IL CODICE DEL PROGETTO</div><h2 id="repo-dialog-title">${html(title)}</h2></div><button type="button" class="ops-icon" data-repo-close aria-label="Chiudi finestra">✕</button></div>${body}<div class="ops-dialog-footer">${footer||'<button type="button" class="ops-button" data-repo-close>Chiudi</button>'}</div>`;
    if(!dialog.open)dialog.showModal();syncLocks();
  }
  function form(title,body,label,submit) {
    view={kind:'form'};
    shell(title,`<form id="repo-form"><div class="ops-form-body">${body}</div><p class="ops-form-error" role="alert" hidden></p></form>`,`<button type="button" class="ops-button" data-repo-close>Annulla</button><button type="submit" form="repo-form" class="ops-button is-primary" data-repo-mutation>${html(label)}</button>`);
    dialog.querySelector('form').addEventListener('submit',async event=>{
      event.preventDefault();if(locked())return;const el=event.currentTarget;if(!el.reportValidity())return;const data=new FormData(el),box=dialog.querySelector('.ops-form-error');box.hidden=true;saving=true;syncLocks();
      try{const after=await submit(data,el);dialog.close();saving=false;syncLocks();if(after)after();}
      catch(e){box.textContent=e.status===409?`${e.message} Chiudi il modulo e aggiorna l’incarico prima di riprovare.`:e.message;box.hidden=false;box.scrollIntoView({block:'nearest'});}
      finally{saving=false;syncLocks();schedule();}
    });
  }
  function checkFields(check={label:'',program:'',args:[]}) {return `<fieldset class="repo-check-fields"><legend>Controllo</legend>${field('Nome del controllo','checkLabel',check.label)}<div class="repo-check-command">${field('Programma','checkProgram',check.program)}${field('Argomenti · array JSON','checkArgs',JSON.stringify(check.args))}</div><button type="button" class="ops-text-button is-danger" data-repo-action="remove-check">Rimuovi controllo</button></fieldset>`;}
  function register() {
    if(locked())return;const projects=context.projects.filter(allowed);if(!projects.length){toast('Crea prima un progetto o mostra tutti gli ambiti.');return;}
    const chosen=projects.find(item=>item.id===context.projectId)||projects[0];
    form('Collega il repository',`<p class="ops-form-intro">Il percorso deve esistere sul computer che ospita questo studio. Il collegamento non avvia Codex.</p><div class="ops-field"><label for="repo-project">Progetto dello studio</label><select id="repo-project" name="projectId" required>${projects.map(item=>`<option value="${html(item.id)}"${chosen.id===item.id?' selected':''}>${html(item.title)} · ${html(scopeName(item.scopeId))}</option>`).join('')}</select></div>${field('Percorso della repository Git','path')}${snapshot.suggestedPath?'<button type="button" class="ops-text-button" data-repo-action="use-suggested">Usa il percorso di Fuori Studio</button>':''}<div class="repo-title-row"><h3>Controlli da eseguire</h3>${help('Comandi reali','Ogni controllo esegue un programma con argomenti separati, senza shell. Gli argomenti sono un array JSON: per npm test scrivi ["test"]. Non usare pipe, glob o variabili di shell. Sono consentiti solo programmi e comandi di verifica supportati dal server; installazioni e comandi di shell non sono ammessi.')}</div><p class="ops-hint">Questi comandi gireranno nella copia di lavoro e possono eseguire codice. Personalizzali per il progetto; serve almeno un controllo.</p><div id="repo-check-fields">${checkFields({label:'Test',program:'npm',args:['test']})}${checkFields({label:'Verifica del progetto',program:'npm',args:['run','check']})}</div><button type="button" class="ops-button" data-repo-action="add-check">＋ Aggiungi controllo</button><p class="repo-notice">Viene usato il codice salvato nell’ultimo commit HEAD. Le modifiche locali non committate restano escluse. L’approvazione conserva una patch: il merge e il push rimangono una tua scelta separata.</p>`,'Collega al progetto',async(data,el)=>{
      const selected=project(data.get('projectId'));if(!selected)throw Error('Seleziona un progetto esistente.');
      const checks=[...el.querySelectorAll('.repo-check-fields')].map(row=>{let args;try{args=JSON.parse(row.querySelector('[name="checkArgs"]').value);}catch{throw Error('Gli argomenti devono essere un array JSON, per esempio ["run", "check"].');}if(!Array.isArray(args)||args.some(value=>typeof value!=='string'))throw Error('Ogni argomento deve essere una stringa nell’array JSON.');return {label:row.querySelector('[name="checkLabel"]').value.trim(),program:row.querySelector('[name="checkProgram"]').value.trim(),args};});
      if(!checks.length)throw Error('Aggiungi almeno un controllo.');await mutation('register',{projectId:selected.id,scopeId:selected.scopeId,path:data.get('path').trim(),checks});toast('Repository collegato. Ora puoi preparare un incarico.');
    });
  }
  function create(repo) {
    form('Un incarico sul codice',`<p class="ops-form-intro"><strong>${html(repo.name)}</strong> · ${html(project(repo.projectId)?.title)}. Verrà preparato un incarico da avviare separatamente.</p>${field('Titolo della modifica','title')}${field('Obiettivo, vincoli e risultato atteso','brief','',true)}<p class="ops-hint">Descrivi quali comportamenti devono cambiare e come verificarli. Non inserire credenziali nel brief.</p>`,'Prepara incarico',async data=>{const before=new Set(snapshot.runs.map(item=>item.id));await mutation('create',{repositoryId:repo.id,title:data.get('title').trim(),brief:data.get('brief').trim()});const saved=snapshot.runs.find(item=>!before.has(item.id));return saved?()=>showRun(saved.id):null;});
  }
  function start(run) {
    form('Avvia il lavoro sul codice',`<p class="ops-form-intro"><strong>${html(run.title)}</strong></p><p>Codex modificherà una copia isolata del commit <code>${html(run.baseCommit?.slice(0,12)||'HEAD')}</code> ed eseguirà i controlli configurati. Usa l’accesso Codex locale e può generare consumo sul tuo account.</p><div class="repo-command-list">${(run.checks||repository(run.repositoryId)?.checks||[]).map(check=>`<div><strong>${html(check.label)}</strong><code>${html(checkCommand(check))}</code></div>`).join('')}</div><p class="repo-notice">Il lavoro esegue codice locale. Il repository originale e le sue modifiche non committate non vengono integrati nella copia. Al termine controllerai diff, risultati e revisione.</p>`,'Avvia Codex e controlli',async()=>{await mutation('start',{id:run.id,expectedVersion:run.version});return()=>showRun(run.id);});
  }
  function revise(run) {
    form('Prepara una nuova revisione',`<p class="ops-form-intro">La patch e i risultati di <strong>${html(run.title)}</strong> restano conservati. La nuova revisione partirà dallo stesso commit di base e includerà il tuo feedback nel brief.</p>${field('Cosa deve cambiare o essere ripreso','feedback','',true)}<p class="ops-hint">Verrà creato un nuovo incarico da avviare esplicitamente. Il lavoro precedente non riprende da solo.</p>`,'Prepara revisione',async data=>{const before=new Set(snapshot.runs.map(item=>item.id));await mutation('requestChanges',{id:run.id,expectedVersion:run.version,feedback:data.get('feedback').trim()});const next=snapshot.runs.find(item=>!before.has(item.id));return()=>showRun(next?.id||run.id);});
  }
  function approve(run) {
    if(!passed(run))return;
    form('Approva questa patch',`<p class="ops-form-intro"><strong>${html(run.title)}</strong> · versione ${run.version}</p><p>I ${run.checks.length} controlli configurati sono passati. Conferma dopo aver letto la patch e la revisione.</p><div class="repo-review-facts"><span>${run.stats?.files||run.files.length} file modificati</span><span class="repo-add">+${run.stats?.additions||0}</span><span class="repo-delete">−${run.stats?.deletions||0}</span></div><p class="repo-notice">L’approvazione conserva il risultato come accettato. Non esegue merge, commit nel repository originale o push.</p><code class="repo-hash">Patch ${html(run.patchHash)}</code>`,'Conferma approvazione',async()=>{await mutation('approve',{id:run.id,expectedVersion:run.version});return()=>showRun(run.id);});
  }
  function proposeMemory(run) {
    form('Un metodo da ricordare',`<p class="ops-form-intro">Crea una proposta nell’ambito <strong>${html(scopeName(run.scopeId))}</strong>, collegata a questa patch approvata. Rivedila in Memoria prima di usarla come contesto.</p>${field('Titolo della memoria','title',run.title)}<div class="ops-field"><label for="repo-memory-type">Tipo</label><select id="repo-memory-type" name="type"><option value="pattern">Metodo riutilizzabile</option><option value="decision">Decisione</option></select></div>${field('Regola o decisione da conservare','content','',true)}`,'Crea proposta di memoria',async data=>{await mutation('proposeMemory',{id:run.id,expectedVersion:run.version,title:data.get('title').trim(),content:data.get('content').trim(),type:data.get('type')});toast('Proposta creata. Rivedila nella memoria di questo ambito.');return()=>showRun(run.id);});
  }
  function patchMarkup(patch){return patch.split('\n').map(line=>`<span class="${line.startsWith('+++')||line.startsWith('---')?'repo-diff-file':line.startsWith('+')?'repo-diff-add':line.startsWith('-')?'repo-diff-remove':line.startsWith('@@')?'repo-diff-hunk':''}">${html(line)||' '}</span>`).join('');}
  function showRun(id) {
    const run=runFor(id);if(!run)return;const repo=repository(run.repositoryId),scroll=dialog.scrollTop,opened=[...dialog.querySelectorAll('details[open][data-detail]')].map(el=>el.dataset.detail);view={kind:'run',id};
    const patch=patches.get(`${id}:${run.patchHash}`);
    const checks=(run.checks||[]).map(check=>`<details class="repo-check-result" data-detail="check-${html(check.label)}"><summary><span><strong>${html(check.label)}</strong><code>${html(checkCommand(check))}</code></span><span class="repo-check-state is-${html(check.status)}">${html(checkNames[check.status]||check.status)}</span></summary><div><p class="ops-hint">${check.exitCode===null||check.exitCode===undefined?'Nessun codice di uscita':`Codice di uscita: ${Number(check.exitCode)}`} ${Number.isFinite(check.durationMs)?`· ${(check.durationMs/1000).toFixed(1)} s`:''}${check.truncated?' · Log troncato':''}</p><pre class="repo-log">${html(check.output||'Nessun output disponibile.')}</pre></div></details>`).join('');
    const review=typeof run.review==='string'?run.review:run.review?.text;
    shell(run.title,`<div class="ops-task-body repo-run-body"><div class="ops-task-meta">${badge(run)}<span>${html(stages[run.stage]||run.stage||'')}</span><span>v${run.version} · ${html(date(run.updatedAt))}</span></div><p class="repo-source">${html(repo?.name||'Repository')} · ${html(scopeName(run.scopeId))} · base <code>${html(run.baseCommit?.slice(0,12)||'HEAD')}</code></p>${run.error?`<p class="ops-error" role="alert">${html(run.error)}</p>`:''}${run.dependencies?.reason?`<p class="repo-notice">${html(run.dependencies.reason)}</p>`:''}<details class="ops-disclosure" data-detail="brief"><summary>Obiettivo e vincoli</summary><p class="ops-prewrap">${html(run.brief)}</p>${run.feedback?`<h3 class="repo-feedback-title">Feedback della revisione</h3><p class="ops-prewrap">${html(run.feedback)}</p>`:''}</details>${run.summary?`<section class="repo-summary"><h3>Risultato del lavoro</h3><p>${html(run.summary)}</p></section>`:''}<section><div class="repo-title-row"><h3>Controlli</h3>${help('Che cosa confermano i controlli','L’approvazione è disponibile solo per una patch non vuota con tutti i controlli configurati superati. Leggi comunque il diff e la revisione: un test passato non garantisce ogni comportamento.')}</div><div class="repo-check-results">${checks||'<p class="ops-hint">Nessun controllo registrato.</p>'}</div></section>${run.files?.length?`<section><div class="repo-title-row"><h3>Modifiche proposte</h3><div class="repo-review-facts"><span>${run.stats?.files||run.files.length} file</span><span class="repo-add">+${run.stats?.additions||0}</span><span class="repo-delete">−${run.stats?.deletions||0}</span></div></div><div class="repo-files">${run.files.map(file=>`<div><code>${html(file.path)}</code><span>${html(file.status)} <b class="repo-add">+${Number(file.additions)||0}</b> <b class="repo-delete">−${Number(file.deletions)||0}</b></span></div>`).join('')}</div>${run.patchHash?`<div class="repo-patch-actions"><button type="button" class="ops-button" data-repo-action="patch" data-id="${html(id)}"${patchLoading?' disabled':''}>${patchLoading?'Caricamento…':patch?'Nascondi diff':'Leggi il diff'}</button><button type="button" class="ops-button" data-repo-action="download" data-id="${html(id)}">Scarica patch</button></div>${patch?`<pre class="repo-diff" tabindex="0" aria-label="Diff della patch">${patchMarkup(patch)}</pre>`:''}`:''}</section>`:''}${run.review?`<section class="repo-review"><div class="repo-title-row"><h3>Revisione del codice</h3><span class="repo-local">${run.review.status==='unavailable'?'Non disponibile':run.review.status==='pending'?'In attesa':'Codex'}</span></div><p>${html(review||run.review.error||'La revisione non contiene un risultato disponibile.')}</p><small>Una revisione AI aiuta il controllo, ma la decisione resta tua.</small></section>`:''}${run.status==='review'&&!passed(run)?`<p class="repo-notice">${run.decision?.status==='changes_requested'?'Questo tentativo è stato sostituito da una nuova revisione. La patch resta consultabile.':'Approvazione non disponibile: occorrono una patch non vuota e tutti i controlli configurati superati e validi.'}</p>`:''}${run.decision?`<section class="repo-decision"><h3>Decisione conservata</h3><p>${html(typeof run.decision==='string'?run.decision:run.decision.feedback||({approved:'Patch approvata',changes_requested:'Nuova revisione richiesta'})[run.decision.status]||run.decision.kind||'Decisione registrata')}</p>${run.decision.nextRunId?`<button type="button" class="ops-text-button" data-repo-action="run" data-id="${html(run.decision.nextRunId)}">Apri la nuova revisione ↗</button>`:''}</section>`:''}<details class="ops-disclosure ops-events" data-detail="events"><summary>Attività dell’incarico</summary><ol>${(run.events||[]).map(event=>`<li><time>${html(date(event.at||event.createdAt))}</time><span>${html(event.message||event.text||event.type||event.kind)}</span></li>`).join('')||'<li>Nessun evento registrato.</li>'}</ol></details><p class="repo-footnote">La patch resta separata dal repository originale. Nessun merge o push automatico.</p></div>`,`<button type="button" class="ops-button" data-repo-close>Chiudi</button><button type="button" class="ops-button" data-repo-action="refresh-run" data-id="${html(id)}">Aggiorna</button>${run.status==='queued'?`<button type="button" class="ops-button is-primary" data-repo-action="start" data-id="${html(id)}" data-repo-mutation>Avvia Codex</button>`:''}${run.status==='running'?`<button type="button" class="ops-button" data-repo-action="pause" data-id="${html(id)}" data-repo-mutation>Ferma il lavoro</button>`:''}${['review','failed','paused'].includes(run.status)?`<button type="button" class="ops-button" data-repo-action="revise" data-id="${html(id)}" data-repo-mutation>Chiedi una revisione</button>`:''}${run.status==='review'?`<button type="button" class="ops-button is-primary" data-repo-action="approve" data-id="${html(id)}" data-repo-mutation${passed(run)?'':' disabled'}>Approva patch</button>`:''}${run.status==='completed'&&run.decision?.status==='approved'?`<button type="button" class="ops-button is-primary" data-repo-action="memory" data-id="${html(id)}" data-repo-mutation>Crea memoria proposta</button><button type="button" class="ops-button" data-repo-action="outcome" data-id="${html(id)}" data-repo-mutation>Valuta risultato</button>`:''}`);
    for(const el of dialog.querySelectorAll('details[data-detail]'))el.open=opened.includes(el.dataset.detail);dialog.scrollTop=scroll;
  }
  async function readPatch(run,{download=false}={}) {
    const key=`${run.id}:${run.patchHash}`;
    if(!download&&patches.has(key)){patches.delete(key);showRun(run.id);return;}
    patchLoading=true;if(!download)showRun(run.id);
    try{const response=await fetch(`/api/repositories/patch?id=${encodeURIComponent(run.id)}`,{cache:'no-store'});if(!response.ok){let value;try{value=await response.json();}catch{}throw Error(value?.error||'Non è stato possibile caricare la patch.');}const patch=await response.text();if(download){const url=URL.createObjectURL(new Blob([patch],{type:'text/x-diff;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`${run.id}.patch`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}else{patches.set(key,patch);while(patches.size>3)patches.delete(patches.keys().next().value);}}
    catch(e){toast(e.message);}finally{patchLoading=false;if(view?.kind==='run'&&view.id===run.id&&dialog.open)showRun(run.id);}
  }
  async function pause(run){if(locked())return;saving=true;syncLocks();try{await mutation('pause',{id:run.id,expectedVersion:run.version});showRun(run.id);}catch(e){toast(e.message);}finally{saving=false;syncLocks();}}
  function click(event) {
    const close=event.target.closest('[data-repo-close]');if(close){if(!saving)dialog.close();return;}
    const button=event.target.closest('[data-repo-action]');if(!button||button.disabled)return;
    const {repoAction:action,id}=button.dataset;
    if(action==='refresh'||action==='refresh-run'){void load();return;}
    if(action==='register'){register();return;}
    if(action==='new-project'){onNewProject();return;}
    if(action==='create'){const repo=repository(id);if(repo&&!locked())create(repo);return;}
    if(action==='use-suggested'){dialog.querySelector('[name="path"]').value=snapshot.suggestedPath;return;}
    if(action==='add-check'){dialog.querySelector('#repo-check-fields').insertAdjacentHTML('beforeend',checkFields());return;}
    if(action==='remove-check'){button.closest('.repo-check-fields').remove();return;}
    const run=runFor(id);if(!run)return;
    if(action==='outcome'&&run.status==='completed'&&run.decision?.status==='approved'){dialog.close();onOutcome({runId:run.id,title:run.title});return;}
    if(action==='run'){showRun(id);return;}if(action==='patch'||action==='download'){void readPatch(run,{download:action==='download'});return;}
    if(locked())return;
    if(action==='start'&&run.status==='queued')start(run);if(action==='pause'&&run.status==='running')void pause(run);if(action==='revise'&&['review','failed','paused'].includes(run.status))revise(run);if(action==='approve')approve(run);if(action==='memory'&&run.status==='completed'&&run.decision?.status==='approved')proposeMemory(run);
  }
  host.addEventListener('click',click);dialog.addEventListener('click',click);
  dialog.addEventListener('close',()=>{if(!dialog.open)view=null;});dialog.addEventListener('cancel',event=>{if(saving)event.preventDefault();});
  return {load,setContext(value){context={...context,...value};render();},setVisible(value){visible=Boolean(value);host.hidden=!visible;render();if(visible&&!loaded&&!loading)void load();},setBusy(value){busy=Boolean(value);syncLocks();},getSnapshot:()=>snapshot,dispose(){disposed=true;loadVersion++;clearTimeout(pollTimer);document.removeEventListener('visibilitychange',visibility);window.removeEventListener('studio-session-expired',expire);host.removeEventListener('click',click);dialog.remove();patches.clear();}};
}
